const UNKNOWN_AUTHOR = "unknown";

function getAuthorName(author) {
  return author?.username ?? UNKNOWN_AUTHOR;
}

function formatCommentDate(createdAt) {
  return createdAt ? new Date(createdAt).toLocaleDateString() : "";
}

function CommentRow({ body, author, createdAt }) {
  const username = getAuthorName(author);
  const date = formatCommentDate(createdAt);

  return (
    <div className="comment">
      <p className="comment-body">{body}</p>
      <p className="comment-meta">
        {username} · {date}
      </p>
    </div>
  );
}

export default CommentRow;

function articleCommentsUrl(slug) {
  return `/api/articles/${encodeURIComponent(slug)}/comments`;
}

async function requestJson(url, failureMessage, options = {}) {
  const res = await fetch(url, options);

  if (!res.ok) {
    throw new Error(`${failureMessage}: ${res.status}`);
  }

  return res.json();
}

export async function getComments(slug, options = {}) {
  const data = await requestJson(
    articleCommentsUrl(slug),
    "Failed to load comments",
    options,
  );

  return data.comments;
}

import CommentFeed from "./CommentFeed";

const SLUG = "a1";

function App() {
  return (
    <main className="page">
      <h1>Feed</h1>
      <CommentFeed slug={SLUG} />
    </main>
  );
}

export default App;

export const DEFAULT_ARTICLE_SLUG = "a1";
export const COMMENT_LOAD_ERROR = "Failed to load comments";
export const UNKNOWN_AUTHOR = "unknown";

